(699,	1,	'2026-09-27 10:07:34',	'2026-09-27 06:37:34',	'',	'Local Flavors: Journeying into the Heart of Cultures Through Local Kitchens and Traditional Foods',	'',	'inherit',	'open',	'closed',	'',	'local-flavors-culinary-tourism-lifestyle-guide-banner-2',	'',	'',	'2026-09-27 10:16:14',	'2026-09-27 06:46:14',	'',	701,	'http://localhost:82/wp-content/uploads/2026/09/local-flavors-culinary-tourism-lifestyle-guide-banner.webp',	0,	'attachment',	'image/webp',	0),
