(753,	1,	'2026-09-27 12:17:11',	'2026-09-27 08:47:11',	'',	'Desert Trekking: Golden Silence, Dancing Sand Dunes, and the Magic of Boundless Skies',	'',	'inherit',	'open',	'closed',	'',	'desert-trekking-golden-sand-dunes-travel-guide-banner-2',	'',	'',	'2026-09-27 12:20:40',	'2026-09-27 08:50:40',	'',	755,	'http://localhost:82/wp-content/uploads/2026/09/desert-trekking-golden-sand-dunes-travel-guide-banner.webp',	0,	'attachment',	'image/webp',	0),
