  `updated_at` bigint unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `user_default` (`user_id`,`is_default`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;


DROP TABLE IF EXISTS `wp_voiceweb_auth_challenges`;
CREATE TABLE `wp_voiceweb_auth_challenges` (
  `id` char(64) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `phone` varchar(11) COLLATE utf8mb4_unicode_520_ci NOT NULL,
